/**
 * The curriculum pages (Daily Teaching System, Part 6): for one framework, one grade and one subject, the list of the
 * framework's objectives with what the site has for each line.
 *
 *   content/curriculum-pages/pages.<loc>.json   GENERATED by scripts/curriculum-pages/assemble.js
 *   content/curriculum-pages/ui.<loc>.json      the pages' own strings
 *
 * A line shows the objective's own official code and OUR description of what the children do, never the wording of
 * the objective (the rule of the curriculum registry, scripts/curricula/show.js).
 */
export interface CurriculumLesson { unit: string; unitTitle: string; unitGrade: string; n: number; title: string }
export interface CurriculumPaper { title: string; core: string }
export interface CurriculumItem {
  code: string;
  state: 'taught' | 'near';
  rel?: 'prepares' | 'extends';
  text: string;
  lessons?: CurriculumLesson[];
  papers?: CurriculumPaper[];
}
export interface CurriculumGroup { title: string; items: CurriculumItem[]; open?: string[] }
export interface CurriculumPageData {
  id: string;
  slug: string;
  status: 'pilot' | 'live';
  registry: string;
  framework: string;
  frameworkShort: string;
  frameworkTitle: string;
  publisher: string;
  year: string;
  officialDocument: string;
  grade: string;
  subject: string;
  title: string;
  metaTitle: string;
  metaDescription: string;
  counts: { objectives: number; taught: number; near: number; open: number; lessons: number };
  groups: CurriculumGroup[];
}
export type CurriculumUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T;
  try {
    const mod = await importer();
    cache.set(key, mod.default);
    return mod.default as T;
  } catch {
    cache.set(key, null);
    return null;
  }
}
export async function getCurriculumPages(locale: string): Promise<CurriculumPageData[]> {
  const f = await load<{ pages: CurriculumPageData[] }>(`pages.${locale}`, () => import(`@/content/curriculum-pages/pages.${locale}.json`));
  return f?.pages ?? [];
}
export const getCurriculumUi = (locale: string) => load<CurriculumUi>(`ui.${locale}`, () => import(`@/content/curriculum-pages/ui.${locale}.json`));
export async function getCurriculumPage(locale: string, slug: string): Promise<CurriculumPageData | null> {
  return (await getCurriculumPages(locale)).find((p) => p.slug === slug) ?? null;
}

/**
 * What the hub of a language lists. Live pages when there are any; a language whose pages are all pilots shows its
 * pilots on a noindex hub (that is how a new language is read before it is published); no pages = no hub (404).
 */
export async function listedCurriculumPages(locale: string): Promise<{ live: boolean; pages: CurriculumPageData[] }> {
  const pages = await getCurriculumPages(locale);
  const livePages = pages.filter((p) => p.status === 'live');
  if (livePages.length) return { live: true, pages: livePages };
  return { live: false, pages };
}

/** the fragment of a code on its curriculum page */
export const codeAnchor = (code: string) => 'code-' + code.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/**
 * Where an objective is on the LIVE curriculum pages of a language, by what a unit page shows for it ("Common Core
 * K.CC.A.1"): the label on a unit page links to the line of the checklist (PLAN Part 6: no crawlable filter
 * parameter, a plain link). A pilot page is linked from nowhere.
 */
export async function curriculumCodeLinks(locale: string): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const p of await getCurriculumPages(locale)) {
    if (p.status !== 'live') continue;
    for (const g of p.groups) for (const it of g.items) { const k = `${p.frameworkShort} ${it.code}`; if (!out[k]) out[k] = `/${locale}/curriculum/${p.slug}#${codeAnchor(it.code)}`; }
  }
  return out;
}

/** the pages of one framework and subject, in the order of the grades: the sets the hub and the "more" list show */
export function curriculumSets(pages: CurriculumPageData[]): { key: string; frameworkShort: string; subject: string; pages: CurriculumPageData[] }[] {
  const out: { key: string; frameworkShort: string; subject: string; pages: CurriculumPageData[] }[] = [];
  for (const p of pages) {
    const key = p.framework;
    let set = out.find((s) => s.key === key);
    if (!set) { set = { key, frameworkShort: p.frameworkShort, subject: p.subject, pages: [] }; out.push(set); }
    set.pages.push(p);
  }
  return out;
}
